/* V8 access and folder system */
[data-access="viewer"] .adminOnly{display:none!important}
.rolePill{display:inline-flex;align-items:center;gap:6px;padding:7px 10px;border-radius:999px;background:var(--soft);border:1px solid var(--line);font-size:12px;font-weight:900;color:var(--muted)}
[data-access="admin"] .rolePill{color:var(--brand)}
[data-access="viewer"] .rolePill{color:var(--good)}
.cloudStatus[data-state="saved"]{color:var(--good);border-color:rgba(20,160,111,.35)}
.cloudStatus[data-state="saving"],.cloudStatus[data-state="loading"]{color:var(--brand)}
.cloudStatus[data-state="conflict"],.cloudStatus[data-state="error"]{color:var(--bad);border-color:rgba(216,73,86,.4)}
.folderBlock{border:1px solid var(--line);border-radius:14px;background:var(--panel2);margin:8px 0;overflow:hidden}
.folderHead{display:flex;align-items:center;gap:8px;padding:9px 10px;font-weight:900;cursor:pointer}
.folderHead.active{background:rgba(49,92,246,.10);color:var(--brand)}
.folderFiles{padding:0 6px 7px 18px}
.folderFiles .item{margin-top:4px}
.compareBox{border:1px solid var(--line);background:linear-gradient(180deg,var(--panel),var(--panel2));border-radius:16px;padding:10px;margin:10px 0}
.compareHead{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:8px}
.compareMini{width:100%;border-collapse:collapse;font-size:12px}
.compareMini th,.compareMini td{padding:7px 8px;border-bottom:1px solid var(--line);text-align:left;white-space:nowrap}
.compareMini td:nth-child(2),.compareMini td:nth-child(3),.compareMini td:nth-child(4){text-align:right;font-variant-numeric:tabular-nums}
.viewerNotice{background:#f0fff8;border:1px solid rgba(20,160,111,.25);color:#0b7a50;padding:8px 10px;border-radius:12px;font-size:12px;font-weight:800}
[data-theme="dark"] .viewerNotice{background:rgba(20,160,111,.12)}
.lockedHint{font-size:12px;color:var(--muted);padding:6px 0}
[data-theme="dark"] .btn.danger{border-color:rgba(216,73,86,.45);background:rgba(216,73,86,.14);color:#ffb8c0}
[data-theme="dark"] .iframePreview{background:#0a1324}
[data-theme="dark"] .viewerNotice{border-color:rgba(20,160,111,.35);color:#9ae8cc}

.btn{color:var(--text);background:linear-gradient(180deg,rgba(255,255,255,.14),rgba(255,255,255,.04));border-color:rgba(126,153,196,.36)}
.btn.primary{background:linear-gradient(135deg,#264fd8,#006fae,#007866);border-color:rgba(143,224,255,.84);color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.58)}
.btn.primary:hover{box-shadow:0 12px 30px rgba(0,0,0,.24),0 0 0 2px rgba(31,231,255,.16),0 0 18px rgba(0,240,200,.22)}
.btn.ghost{color:var(--text)}
[data-theme="light"] .btn{background:linear-gradient(180deg,#fff,#eef4ff);border-color:rgba(92,116,158,.34);color:#142033}
[data-theme="light"] .btn.primary{background:linear-gradient(135deg,#244bd4,#006aa8,#007563);border-color:rgba(0,106,168,.42);color:#fff}
.modalBackdrop{background:rgba(2,8,18,.78);backdrop-filter:blur(10px)}
.modal{background:#f8fbff;color:#142033;border-color:rgba(199,214,238,.95);box-shadow:0 34px 90px rgba(0,0,0,.42);isolation:isolate}
.modalHead,.modalBody,.modalFoot{background:#f8fbff;color:#142033}
.modalHead,.modalFoot{border-color:#d5e0f3}
.modal .field label{color:#4f5f78}
.modal input,.modal select,.modal textarea{background:#fff;color:#142033;border-color:#b7c8e5}
.modal input:focus,.modal select:focus,.modal textarea:focus{border-color:#008fcf;box-shadow:0 0 0 3px rgba(0,143,207,.16)}
.modal .hintBox,.modal .check,.modal .wizardPreview{background:#eef4ff;color:#53647f;border-color:#c9d7ef}
.modal .check span{color:#53647f}
.modal .btn:not(.primary):not(.danger){background:linear-gradient(180deg,#fff,#eef4ff);border-color:#b7c8e5;color:#142033}
.modal .pill{background:#edf3ff;color:#4f5f78;border-color:#c9d7ef}

