  .topbar .spacer{display:none}
  .topbar>.btn,.topbar>.rolePill{flex:0 0 auto;min-height:40px}
  #companyNameInput{flex:0 0 240px;min-width:0!important}
  .layout{padding:10px}
  .grid{grid-template-columns:repeat(auto-fit,minmax(300px,1fr))}
